import React from "react";
import { useTranslation } from "gatsby-plugin-react-i18next";
import industrialImages from "../images"; // objeto con imágenes indexadas (ej. { industrial_gun_spray: ..., heavy_weaponry: ... })

const Industrial: React.FC = () => {
  const { t } = useTranslation();

  const data = t("industrial", { returnObjects: true }) as {
    title: string;
    subtitle: string;
    backgroundImage: string;
    products: {
      name: string;
      use: string;
      format: string;
      image: string;
      description: { item: string }[];
    }[];
  }[];

  return (
    <section className="w-full">
      {data.map((category, index) => (
        <div  key={index}>
          <div
            key={index}
            className="relative w-full h-[300px] sm:h-[962px] bg-cover bg-center bg-no-repeat"
            style={{
              backgroundImage: `url(${
                industrialImages[category.backgroundImage].src
              })`,
            }}
          >
            <div
              className="w-full h-full space-y-2 bg-transparent text-right flex flex-col justify-end text-DarkGreen"
              style={{
                backgroundImage: `linear-gradient(to bottom, 
                    rgba(194, 193, 188, 1) 0%, 
                    rgba(194, 193, 188, 0) 25%, 
                    rgba(194, 193, 188, 0) 75%, 
                    rgba(194, 193, 188, 1) 100%)`,
              }}
            >
              <h2 className="title-mob sm:title font-semibold uppercase mr-6 sm:mr-24" dangerouslySetInnerHTML={category.title ? { __html: category.title } : { __html: "" }} />
              <h3 className="header-mob sm:header font-bold uppercase mr-6 sm:mr-24">
                {category.subtitle}
              </h3>
            </div>
          </div>

          {/* Contenido sobre la imagen */}
          <div className="flex flex-col sm:flex-row justify-end items-start sm:items-center px-6 sm:px-16 py-12 sm:py-28 text-black gap-6 bg-gradient-to-b sm:bg-gradient-to-r">
            {category.products.map((product, i) => (
              <div key={i} className="flex flex-col sm:flex-row">
                <div className="w-full sm:w-1/2 flex flex-col">
                  <div className="block sm:hidden uppercase mb-8">
                    <h4 className="header-mob sm:header text-DarkGreen">
                      {product.name}
                    </h4>
                    <h5 className="header-mob sm:header text-DarkGrayText">
                      {product.use}
                    </h5>
                    <p className="subheader-mob-2 sm:subheader text-DarkGrayText">
                      {product.format}
                    </p>
                  </div>
                  <img
                    src={industrialImages[product.image].src}
                    alt={product.name}
                    className="w-full"
                  />
                </div>
                <div className="w-full sm:w-1/2 flex flex-col gap-6 justify-between">
                  <div className="hidden sm:block uppercase mt-24">
                    <h4 className="header-mob sm:header text-DarkGreen">
                      {product.name}
                    </h4>
                    <h5 className="header-mob sm:header text-DarkGrayText">
                      {product.use}
                    </h5>
                    <p className="subheader-mob-2 sm:subheader text-DarkGrayText">
                      {product.format}
                    </p>
                  </div>

                  <ul className="space-y-4 body-mob sm:body text-DarkGrayText mb-0">
                    {product.description.map((desc, j) => (
                      <li
                        key={j}
                        dangerouslySetInnerHTML={{ __html: desc.item }}
                      />
                    ))}
                  </ul>
                </div>
              </div>
            ))}
          </div>
        </div>
      ))}
    </section>
  );
};

export default Industrial;
