import React, { useEffect, useRef, useState } from "react";
import { useForm, Controller, SubmitHandler } from "react-hook-form";
import { yupResolver } from "@hookform/resolvers/yup";
import * as yup from "yup";
import { TextField, Box, Typography } from "@mui/material";
import { useTranslation } from "react-i18next";
import { db } from "../../firebaseConfig";
import { collection, addDoc, Timestamp } from "firebase/firestore";
import ButtonComponent from "./buttons";
import emailjs from "@emailjs/browser";
import { buildEmailMessage, getEmailJsConfig } from "../utils/emailjs";



const schema: yup.ObjectSchema<FormData> = yup.object({
  email: yup.string().email("Invalid email").required("Email is required"),

}) as yup.ObjectSchema<FormData>;

type FormData = {
  email: string;
};

export default function SubscribeForm() {
  const [sending, setSending] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  const [categoryOpen, setCategoryOpen] = useState(false);
  const categoryWrapRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (!categoryOpen) return;
    const handleClickOutside = (event: MouseEvent) => {
      const wrap = categoryWrapRef.current;
      if (wrap && !wrap.contains(event.target as Node)) {
        setCategoryOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, [categoryOpen]);

  const { t } = useTranslation();

  const {
    control,
    handleSubmit,
    reset,
    formState: { errors },
  } = useForm<FormData>({
    resolver: yupResolver(schema),
    mode: "onChange",
    defaultValues: {
      email: "",
    },
  });

  const onSubmit: SubmitHandler<FormData> = async (data) => {
    setSending(true);
    try {
      await addDoc(collection(db, "subscribeForm"), {
        ...data,
        createdAt: Timestamp.now(),
      });

      const emailConfig = getEmailJsConfig();

      if (!emailConfig) {
        console.error("Missing EmailJS environment variables");
        setSending(false);
        return;
      }

      const emailMessage = buildEmailMessage("subscribe", {
        email: data.email,
      });

      await emailjs.send(
        emailConfig.serviceId,
        emailConfig.templateId,
        emailMessage,
        emailConfig.publicKey
      );

      reset();
      setSubmitted(true);
    } catch (error) {
      console.error("Error submitting form:", error);
    } finally {
      setSending(false);
    }
  };

  return (
    <Box
      component="form"
      onSubmit={handleSubmit(onSubmit)}
      className="w-full sm:w-[323px]"
    >
      {submitted ? (
        <Box className="flex flex-col items-center mt-12 p-4 text-center backdrop-blur-xl">
          <Typography
            variant="h6"
            className="text-LightGrayText body-mob sm:body mb-2"
          >
            {t("subscribeForm.thankYou") || "Thank you for your message!"}
          </Typography>
          <Typography className="text-LightGrayText body-mob sm:body mb-4">
            {t("subscribeForm.confirmation") ||
              "We will get back to you shortly."}
          </Typography>
          <button
            type="button"
            onClick={() => {
              reset();
              setSubmitted(false);
            }}
            className="w-full
              !backdrop-blur-md 
              rounded-lg py-4 px-4 body-4
              bg-white/10 hover:bg-white/20 
              border border-white border-solid"
          >
            <span className="text-white body-mob sm:body lowercase !first-letter:uppercase">
              {t("subscribeForm.backToForm") || "Back to Form"}
            </span>
          </button>
        </Box>
      ) : (
        <>
          <div className="mb-6 text-white header-mob sm:large-text uppercase sm:first-letter:uppercase sm:normal-case text-center">
            {t("subscribeForm.subtitle")}
          </div>



          {/* Email */}
          <Controller
            name="email"
            control={control}
            render={({ field }) => (
              <TextField
                {...field}
                InputLabelProps={{ shrink: false }} 
                label=" "
                hiddenLabel
                placeholder={
                  t("subscribeForm.placeholder") || "name@email.com"
                }
                error={!!errors.email}
                fullWidth
                margin="dense"
                variant="outlined"
                className="body-mob sm:body !text-LightGrayText"
                helperText={errors.email?.message || ""}
              />
            )}
          />

          <div className="mt-2 text-LightGrayText backdrop-blur-xl">
            <ButtonComponent
              isDisabled={false}
              isSubmit={true}
              sending={sending}
              labelKey="subscribeForm.send"
            />
          </div>
        </>
      )}
    </Box>
  );
}
