import React, { useState } from "react";
import { useForm, Controller, SubmitHandler } from "react-hook-form";
import { yupResolver } from "@hookform/resolvers/yup";
import * as yup from "yup";
import { TextField, Button, Box, Typography } from "@mui/material";
import { useTranslation } from "react-i18next";
import { db } from "../../firebaseConfig";
import { collection, addDoc, Timestamp } from "firebase/firestore";
import emailjs from "@emailjs/browser";
import ButtonComponent from "./buttons";
import { buildEmailMessage, getEmailJsConfig } from "../utils/emailjs";

const schema: yup.ObjectSchema<FormData> = yup.object({
  fullName: yup.string().required("Full name is required"),
  email: yup.string().email("Invalid email").required("Email is required"),
  message: yup.string().required("Message is required"),
}) as yup.ObjectSchema<FormData>;

type FormData = {
  fullName: string;
  email: string;
  message: string;
};

export default function ContactForm() {
  const [sending, setSending] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const { t } = useTranslation();

  const {
    control,
    handleSubmit,
    reset,
    formState: { errors },
  } = useForm<FormData>({
    resolver: yupResolver(schema),
    mode: "onChange",
    defaultValues: {
      fullName: "",
      email: "",
      message: "",
    },
  });

  const onSubmit: SubmitHandler<FormData> = async (data) => {
    setSending(true);
    try {
      await addDoc(collection(db, "contactMessages"), {
        ...data,
        createdAt: Timestamp.now(),
      });

      const emailConfig = getEmailJsConfig();

      if (!emailConfig) {
        console.error("Missing EmailJS environment variables");
        setSending(false);
        return;
      }

      const emailMessage = buildEmailMessage("contact", {
        fullName: data.fullName,
        email: data.email,
        message: data.message,
      });

      await emailjs.send(
        emailConfig.serviceId,
        emailConfig.templateId,
        emailMessage,
        emailConfig.publicKey
      );

      reset();
      setSubmitted(true);
    } catch (error) {
      console.error("Error submitting form:", error);
    } finally {
      setSending(false);
    }
  };

  return (
    <Box
      component="form"
      onSubmit={handleSubmit(onSubmit)}
      className="w-full sm:w-[400px]"
    >
      {submitted ? (
        <Box className="flex flex-col items-center mt-12 p-4 text-center backdrop-blur-xl">
          <Typography variant="h6" className="text-LightGrayText body-mob sm:body mb-2">
            {t("contact.form.thankYou") || "Thank you for your message!"}
          </Typography>
          <Typography className="text-LightGrayText body-mob sm:body mb-4">
            {t("contact.form.confirmation") || "We will get back to you shortly."}
          </Typography>
          <Button
            onClick={() => {
              reset();
              setSubmitted(false);
            }}
            className="w-full
              !backdrop-blur-md 
              rounded-lg py-4 px-4 body-4
              bg-white/10 hover:bg-white/20 
              border border-white border-solid"
          >
            <span className="text-white body-mob sm:body lowercase !first-letter:uppercase">
              {t("contact.form.backToForm") || "Back to Form"}
            </span>
          </Button>
        </Box>
      ) : (
        <>
          <div className="body-mob sm:body mb-6">
            {t("contact.subtitle")}
          </div>

          {/* Full Name */}
          <Controller
            name="fullName"
            control={control}
            render={({ field }) => (
              <TextField
                {...field}
                onBlur={(e) => {
                  field.onBlur(); // ejecuta validación
                }}
                label={t("contact.form.name") || "Name"}
                error={!!errors.fullName}
                fullWidth
                margin="dense"
                variant="outlined"
                className="body-mob sm:body !text-LightGrayText"
                InputLabelProps={{ shrink: true }}
                helperText={errors.fullName?.message || ""}
              />
            )}
          />

          {/* Email */}
          <Controller
            name="email"
            control={control}
            render={({ field }) => (
              <TextField
                {...field}
                label={t("contact.form.email") || "Email"}
                // placeholder="Email"
                error={!!errors.email}
                fullWidth
                margin="dense"
                variant="outlined"
                className="body-mob sm:body !text-LightGrayText"
                InputLabelProps={{ shrink: true }}
                helperText={errors.email?.message || ""}
              />
            )}
          />

          {/* Message */}
          <Controller
            name="message"
            control={control}
            render={({ field }) => (
              <TextField
                {...field}
                value={field.value || " "}
                label={t("contact.form.message") || "Message"}
                error={!!errors.message}
                fullWidth
                multiline
                rows={4}
                margin="dense"
                variant="outlined"
                className="body-mob sm:body !text-LightGrayText"
                helperText={errors.message?.message || ""}
              />
            )}
          />

          <div className="mt-2">
            <ButtonComponent
              isDisabled={false}
              isSubmit={true}
              sending={sending}
            />
          </div>
        </>
      )}
    </Box>
  );
}
