import * as React from "react";
import { graphql, PageProps } from "gatsby";
import data from "../data/data.json";
import { UserProfile } from "../interfaces";
import { useTranslation } from "gatsby-plugin-react-i18next";
import images from "../images";
import Navigation from "../components/nav";
import Icon from "../components/icon";
import Logo from "../components/logo";
import ContactForm from "../components/contactForm";
import Carousel from "../components/carousel";
import Products from "../components/products";
import Industrial from "../components/industrial";
import { SlScreenSmartphone } from "react-icons/sl";
import { HiOutlinePhone } from "react-icons/hi2";
import { useState } from "react";
import SubscribeForm from "../components/subscribeForm";

const userData: UserProfile = data;

const IndexPage: React.FC<PageProps> = () => {
  const [currentYear, setYear] = useState<number | null>(null);

  React.useEffect(() => {
    setYear(new Date().getFullYear());
  }, []);
  const { t } = useTranslation();
  const statements = t("heroBanner.statements", {
    returnObjects: true,
  }) as string[];
  const ourPurposeContent = t("ourPurpose.content", {
    returnObjects: true,
  }) as string[];

  function formatPhoneNumber(phoneNumber: string) {
    const cleanedPhoneNumber = phoneNumber.replace(/\D+/g, "");
    if (cleanedPhoneNumber.startsWith("1")) {
      return `${cleanedPhoneNumber.slice(1, 4)} ${cleanedPhoneNumber.slice(
        4,
        7
      )} ${cleanedPhoneNumber.slice(7, 12)}`;
    } else {
      return cleanedPhoneNumber;
    }
  }
  return (
    <section className="bg-MidGray">
      <Navigation />

      <section
        className={`${styles.container} bg-DarkGreen relative h-full pb-16 bg-cover`}
        id={"start"}
        style={{
          backgroundImage: `url(${images.hero_image.src})`,
          backgroundRepeat: "no-repeat",
          backgroundPosition: "bottom center",
        }}
      >
        <div className="hidden sm:flex justify-end absolute top-24 right-14 z-30 backdrop-blur-xl p-4">
          <SubscribeForm />
        </div>
        {/* Gradient overlay */}
        <div className="absolute bottom-[15%] left-0 right-0 h-[85%] bg-gradient-to-b from-transparent to-DarkGreen opacity-100 pointer-events-none z-10" />
        {/* Frame oscuro sólido del 15% inferior */}
        <div className="absolute bottom-0 left-0 right-0 h-[15%] bg-DarkGreen pointer-events-none z-10" />

        <article className="relative z-20 flex flex-col items-center w-full h-full px-0">
          <div className="max-w-[1720px] w-full mb-[7%] mt-12 sm:mt-[25%] flex">
            <div className="w-[120px] hidden sm:block">
              <Icon fill="Yellow" />
            </div>
          </div>
          <div className="max-w-[1720px] w-full flex flex-col sm:flex-row items-center justify-between">
            <div className="flex flex-wrap flex-row sm:flex-col  sm:hidden">
              {statements.map((item: string, index: number) => (
                <p
                  key={index}
                  className={`${
                    index === 0 && "text-white"
                  } text-Yellow uppercase subheader-mob-1 sm:header mb-0 sm:mb-4 mr-1 sm:mr-0`}
                >
                  {item}
                </p>
              ))}
            </div>
            <div className="w-[50px] block sm:hidden my-28">
              <Icon fill="Yellow" />
            </div>
            <div>
              <div className="w-[270px] sm:w-[717px] mx-auto">
                <Logo />
              </div>
              <h2 className="text-white uppercase subheader-mob-2 sm:subheader mt-[5%] text-center sm:text-left">
                {t("heroBanner.subtitle")}
              </h2>
            </div>

            <div className="hidden sm:flex flex-wrap flex-row sm:flex-col mt-4">
              {statements.map((item: string, index: number) => (
                <p
                  key={index}
                  className={`${
                    index === 0 && "text-white"
                  } text-Yellow uppercase header mb-0 sm:mb-4 mr-1 sm:mr-0`}
                >
                  {item}
                </p>
              ))}
            </div>
          </div>
        </article>
      </section>

      <section
        className={`${styles.container} bg-DarkGreen scroll-mt-16 sm:scroll-mt-8`}
        id={userData.menu[0]}
      >
        <article className="relative z-20 flex flex-col items-center w-full h-full px-0 ">
          <div className="flex flex-col sm:hidden mb-12">
            <div className="border-t border-LightGrayText w-3/4 sm:w-[60%] mx-auto pt-12"></div>
            <SubscribeForm />
            <div className="border-t border-LightGrayText w-3/4 sm:w-[60%] mx-auto mt-12"></div>
          </div>

          <div className="max-w-[1720px] w-full flex flex-col sm:flex-row items-center justify-between">
            <div className="flex flex-wrap flex-col w-full bg-green">
              <h3 className="text-LightGrayText uppercase header-mob sm:subheader mt-2 sm:mt-[10%] mb-8 sm:mb-[30%]">
                {t("ourPurpose.title")}
              </h3>
              {(
                t("ourPurpose.content", { returnObjects: true }) as {
                  item: string;
                }[]
              ).map((item: { item: string }, index: number) => (
                <p
                  key={index}
                  className={`text-MidGray large-text-mob sm:large-text mb-8`}
                >
                  {item.item}
                </p>
              ))}
            </div>
            <div className="hidden sm:flex w-full">
              <div className="opacity-40 w-full ml-[30%]">
                <Icon fill="black" />
              </div>
            </div>
          </div>
        </article>
      </section>

      <section
        className={`${styles.container} bg-gradient-to-b from-DarkGreen to-transparent opacity-100 pt-4 sm:pt-28 scroll-mt-16 sm:-scroll-mt-8`}
        id={userData.menu[1]}
      >
        <div className=" w-full max-w-[1760px] mx-auto">
          <h3 className="header-mob sm:subheader text-LightGrayText uppercase mb-8">
            {t("carousel.title")}
          </h3>
          <Carousel />
        </div>
      </section>

      <section
        className={`${styles.container} scroll-mt-20 sm:scroll-mt-20`}
        id={userData.menu[2]}
      >
        <div className=" w-full max-w-[1760px] mx-auto">
          <Products />
        </div>
      </section>
      <section id={userData.menu[3]} className="scroll-mt-16 sm:scroll-mt-0">
        <div className=" w-full  mx-auto">
          <Industrial />
        </div>
      </section>
      <section className="scroll-mt-16 sm:scroll-mt-0" id={userData.menu[4]}>
        <div
          className="flex h-auto sm:h-[1000px]  bg-[45%_50%] mt-12"
          style={{
            backgroundImage: `url(${images.contact_background.src})`,
            backgroundSize: "cover",
          }}
        >
          <div
            className="w-full flex flex-col sm:flex-row justify-between px-4 sm:px-12 text-white"
            style={{
              backgroundImage: `linear-gradient(to bottom, 
                    rgba(194, 193, 188, 1) 0%, 
                    rgba(194, 193, 188, 0) 25%, 
                    rgba(194, 193, 188, 0) 75%, 
                    rgba(35, 43, 34, 1) 100%)`,
            }}
          >
            <div className="flex items-center">
              <div className="flex flex-col">
                <h2 className="title-mob sm:title mb-4">
                  {t("contact.title")}
                </h2>
                <p className="body-mob sm:body mb-4">{userData.address}</p>
                <p className="body-mob sm:body mb-4">
                  {userData.city}, {userData.province}
                </p>
                <p className="body-mob sm:body mb-4">{userData.postalCode}</p>
                <p className="body-mob sm:body flex mb-4">
                  <HiOutlinePhone />
                  <a className="ml-2" href={`tel:${userData.phone}`}>
                    {formatPhoneNumber(userData.phone)}
                  </a>
                </p>
                <p className="body-mob sm:body flex  mb-4">
                  <SlScreenSmartphone />
                  <a className="ml-2" href={`tel:${userData.cel}`}>
                    {formatPhoneNumber(userData.cel)}
                  </a>
                </p>
              </div>
            </div>
            <div className="flex items-center ">
              <div className="bg-GrayText rounded-[10px] p-2 sm:p-5">
                <ContactForm />
              </div>
            </div>
          </div>
        </div>
      </section>
      <footer className={styles.footerContainer}>
        <div className="flex flex-col sm:flex-row  w-full">
          <div className="flex flex-col w-[75px] sm:w-[123px] self-center">
            <Logo />
          </div>

          <div className="flex flex-col w-full justify-end">
            <div
              className={`justify-end py-6 px-4 text-[12px] text-center sm:text-end text-LightGrayText uppercase`}
            >
              &copy; {currentYear} {data?.name}
            </div>
          </div>
        </div>
      </footer>
    </section>
  );
};

export default IndexPage;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  container: "w-full px-5 sm:px-16",
  section:
    "flex h-96 bg-primary my-8 w-full border border-primary rounded-lg shadow-md",
  title: "head-3 sm:head-1 text-Tofu",
  footerContainer:
    "flex flex-col text-light w-full px-7 bg-DarkGreen py-8 sm:py-0",
};
